card(id="pir", name="Sensore PIR", aka="Passive InfraRed", area="sensori", sub="movimento",
     principles=["piroelettrico"], related=["fotodiodo"],
     hook="Il sensore PIR vede il calore che si muove",
     short="Non emette nulla: un elemento piroelettrico dà un segnale quando l'infrarosso che riceve cambia. Le lenti dividono la stanza in zone, e chi cammina le attraversa una dopo l'altra.",
     steps=["Ogni corpo caldo emette radiazione infrarossa, invisibile ai nostri occhi.",
            "Una lente di Fresnel (la cupoletta di plastica sfaccettata) divide il campo visivo in tante zone e le concentra sul sensore.",
            "Il sensore ha due elementi collegati in modo da sottrarsi: un cambiamento uguale su entrambi si annulla, un corpo che passa li colpisce uno dopo l'altro e genera un impulso."],
     variants=[{"name": "Con lente di Fresnel", "text": "La finestra di plastica sfaccettata che si vede su molti moduli."},
               {"name": "Con specchio a segmenti", "text": "Uno specchio interno concentra l'infrarosso: la finestra è liscia."},
               {"name": "Da soffitto a 360°", "text": "Coprono una stanza intera dall'alto."}],
     note="Un PIR rileva il movimento, non la presenza: una persona ferma, dopo un po', non viene più vista.",
     uses=["Antifurti", "Luci automatiche", "Lampade solari da esterno"],
     diagram="pir",
     images=[img("PIR motion sensor for Arduino oblique view.jpg", "Modulo PIR per Arduino: la cupola bianca è la lente di Fresnel", "Sjilla", "CC BY-SA 4.0"),
             img("PIR Sensor Visonic Next+MCW.jpg", "Sensore PIR di un antifurto: la luce rossa si accende quando rileva movimento", "Geom", "CC BY-SA 4.0")],
     source={"title": "Wikipedia – Passive infrared sensor", "url": "https://en.wikipedia.org/wiki/Passive_infrared_sensor"},
     quiz=[{"q": "Perché un sensore PIR usa due elementi sensibili collegati in modo differenziale?", "options": ["Per rilevare il movimento ignorando i cambiamenti che colpiscono tutto il campo visivo", "Per misurare la temperatura esatta di una persona", "Per emettere e ricevere raggi infrarossi", "Per raddoppiare la portata"], "correct": 0,
            "expl": "Un cambiamento uguale su entrambi (per esempio un lampo) si annulla; un corpo caldo che passa colpisce prima l'uno e poi l'altro."},
           {"q": "Una persona entra in una stanza e poi resta immobile a lungo. Che cosa fa il PIR?", "options": ["Smette di rilevarla", "La rileva per sempre", "Misura la sua temperatura", "Fa scattare l'allarme di continuo"], "correct": 0,
            "expl": "Il PIR reagisce alle variazioni dell'infrarosso ricevuto: se nulla si muove, non c'è variazione e quindi nessun segnale."}])

card(id="hall", name="Sensore a effetto Hall", aka="", area="sensori", sub="magnetici",
     principles=["effetto-hall"], related=["encoder"],
     hook="Effetto Hall: sentire un magnete con la corrente",
     short="Se una corrente attraversa una piastrina sottile dentro un campo magnetico, le cariche in movimento vengono spinte verso un bordo. Tra i due bordi nasce una piccola tensione, che cresce con l'intensità del campo.",
     steps=["Una corrente costante attraversa una piastrina di semiconduttore.",
            "Un campo magnetico perpendicolare spinge le cariche in movimento verso uno dei due bordi.",
            "Le cariche accumulate creano una tensione tra i bordi (tensione di Hall): più il campo è forte, più la tensione è alta. Se il campo si inverte, la tensione cambia segno."],
     variants=[{"name": "Lineare", "text": "L'uscita segue con continuità l'intensità del campo."},
               {"name": "Interruttore (switch)", "text": "L'uscita scatta acceso/spento quando il campo supera una soglia."}],
     uses=["Motori brushless", "Sensori di corrente", "Chiusura del portatile", "Contagiri"],
     diagram="hall", sim="hall",
     images=[img("Hall effect wafer n-doped germanium.jpg", "Piastrina di germanio usata in laboratorio per mostrare l'effetto Hall", "Panoga", "CC BY-SA 4.0")],
     source={"title": "Wikipedia – Effetto Hall", "url": "https://it.wikipedia.org/wiki/Effetto_Hall"},
     quiz=[{"q": "Che cosa succede alla tensione di Hall se si inverte il campo magnetico?", "options": ["Cambia segno", "Raddoppia", "Resta uguale", "Diventa alternata"], "correct": 0,
            "expl": "Invertendo il campo la spinta sulle cariche si inverte: le cariche si accumulano sull'altro bordo e la tensione cambia segno."},
           {"q": "In che verso si muovono gli elettroni rispetto alla corrente convenzionale?", "options": ["In verso opposto", "Nello stesso verso", "Perpendicolare", "Non si muovono"], "correct": 0,
            "expl": "Per convenzione la corrente va dal + al −; gli elettroni, che hanno carica negativa, si muovono al contrario."}])

