card(id="ldr", name="Fotoresistenza (LDR)", aka="Light Dependent Resistor", area="sensori", sub="fotorilevatori",
     principles=["fotoconduttivita"], related=["fotodiodo"],
     hook="La resistenza che si abbassa quando c'è luce",
     short="È una resistenza fatta di un materiale fotoconduttivo, spesso solfuro di cadmio. Al buio conduce poco; quando la luce la colpisce libera cariche al suo interno e la resistenza scende.",
     steps=["Il materiale a serpentina sulla superficie è un semiconduttore fotoconduttivo.",
            "La luce che lo colpisce fornisce energia agli elettroni e li rende liberi di muoversi.",
            "Più cariche libere significa più corrente a parità di tensione: la resistenza diminuisce con la luce."],
     note="È lenta a reagire e poco precisa: va bene per capire se è giorno o notte, non per misure di laboratorio. Contiene cadmio, una sostanza limitata in Europa dalla direttiva RoHS.",
     uses=["Lampioni crepuscolari", "Luci notturne automatiche", "Progetti didattici"],
     images=[img("25mm light-dependent resistor (LDR) (5).jpg", "Fotoresistenza da 25 mm: la serpentina è il materiale sensibile alla luce", "Suyash Dwivedi", "CC BY-SA 4.0")],
     source={"title": "Wikipedia – Fotoresistenza", "url": "https://it.wikipedia.org/wiki/Fotoresistenza"},
     quiz=[{"q": "Che cosa succede alla resistenza di una LDR quando la illumini?", "options": ["Diminuisce", "Aumenta", "Resta uguale", "Diventa infinita"], "correct": 0,
            "expl": "La luce libera cariche nel materiale: il materiale conduce meglio, quindi la resistenza scende."}])

